package com.lianxibu.site.repository.jobs;
import com.lianxibu.site.domain.jobs.BacklogHistoryTelemetry.*;
import com.lianxibu.site.domain.protocol.*;
import java.time.*;import java.nio.charset.StandardCharsets;import java.util.*;import javax.sql.DataSource;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.*;import org.springframework.transaction.support.TransactionSynchronizationManager;
/** Actual pending roots and bounded original runtime-settings history; caller owns its SQL snapshot. */
public final class JdbcBacklogHistory {
 private static final long MAX=9007199254740991L;private static final int CAP=2097152;private final JdbcTemplate sql;private final JdbcBacklogMutationWitness.Scope scope;
 public JdbcBacklogHistory(DataSource source,JdbcBacklogMutationWitness.Scope scope){Objects.requireNonNull(source);if(scope==null||JdbcBacklogMutationWitness.capture(source)!=scope)throw invalid();sql=new JdbcTemplate(source);this.scope=scope;}
 public record Root(String id,int priority,String state,long revision,Instant createdAt,Instant updatedAt,Instant eligibleAt,String stamp){@Override public String toString(){return "BacklogRoot[redacted]";}}
 public record History(String rootId,Instant createdAt,Instant readAt,String stamp,Mutation mutation,Boolean ready,Boolean paused,List<Span> spans,Instant verifiedAfter,long revision){
  public History(String rootId,Instant createdAt,Instant readAt,String stamp,Mutation mutation,Boolean ready,Boolean paused,List<Span> spans,long revision){this(rootId,createdAt,readAt,stamp,mutation,ready,paused,spans,readAt,revision);}
  public History{new Entry(rootId,1,"queued",createdAt,readAt,spans);if(stamp==null||!stamp.matches("[0-9a-f]{64}")||mutation==null||mutation.changedAt().isAfter(readAt)||verifiedAfter==null||verifiedAfter.getNano()%1000!=0||verifiedAfter.isBefore(readAt)||Duration.between(readAt,verifiedAfter).compareTo(Duration.ofSeconds(120))>0||revision<0||revision>MAX)throw invalid();spans=List.copyOf(spans);}
  @Override public String toString(){return "BacklogHistory[redacted]";}
 }
 public Mutation mutation(){readonly();return scope.read();}
 public List<Root> pending(){readonly();var rows=sql.query("SELECT id,priority_no,state,revision,created_at,updated_at,CASE WHEN OCTET_LENGTH(logical_key) BETWEEN 1 AND 16384 THEN logical_key ELSE NULL END,generation,stage_part,record_identity_hash,business_key,task_kind,target_id,call_count,max_attempts,eligible_at FROM jobs WHERE record_kind='logical_task' AND state NOT IN ('succeeded','failed','cancelled','discarded','superseded') ORDER BY id LIMIT 4097",(r,n)->{
   String id=WireValues.id(r.getString(1),false),state=r.getString(3),logical=r.getString(7);int priority=integer(r.getObject(2));long revision=number(r.getObject(4)),generation=number(r.getObject(8)),part=number(r.getObject(9));int calls=integer(r.getObject(14));Instant created=time(r.getTimestamp(5,utc())),updated=time(r.getTimestamp(6,utc()));if(logical==null||!com.lianxibu.site.domain.jobs.BacklogHistoryTelemetry.PENDING.contains(state)||priority<1||priority>14||calls<0||calls>3||integer(r.getObject(15))!=3||updated.isBefore(created)||!"logical_task".equals(r.getString(12))||!id.equals(r.getString(13)))throw invalid();var identity=tools.jackson.databind.json.JsonMapper.shared().createObjectNode();identity.put("record_kind","logical_task");identity.put("natural_key",logical+"\u0000"+generation+"\u0000"+part);String hash=CanonicalJson.hash(CanonicalJson.Domain.IDENTITY,identity);if(!Arrays.equals(r.getBytes(10),HexFormat.of().parseHex(hash))||!("logical_task:"+hash).equals(r.getString(11)))throw invalid();String stamp=sha(id+"\n"+priority+"\n"+state+"\n"+revision+"\n"+created+"\n"+updated+"\n"+hash+"\n"+calls);Instant eligible=time(r.getTimestamp(16,utc()));return new Root(id,priority,state,revision,created,updated,eligible,sha(stamp+"\n"+eligible));
  });if(rows.size()>4096)throw invalid();return List.copyOf(rows);}
 public History read(Root root){readonly();Objects.requireNonNull(root);var rows=sql.query("SELECT CASE WHEN OCTET_LENGTH(value_json) BETWEEN 1 AND ? THEN value_json ELSE NULL END,revision,updated_at FROM runtime_settings WHERE setting_key=?",(r,n)->{String raw=r.getString(1);long revision=number(r.getObject(2));if(raw==null||revision<1)throw invalid();var value=decode(raw,revision);if(!root.id().equals(value.rootId())||!root.createdAt().equals(value.createdAt())||!time(r.getTimestamp(3,utc())).equals(value.readAt()))throw invalid();return value;},CAP,key(root.id()));if(rows.size()>1)throw invalid();return rows.isEmpty()?null:rows.getFirst();}
 public void save(History before,History next){writer();Objects.requireNonNull(next);long expected=before==null?0:before.revision();if(expected==MAX||next.revision()!=expected+1||before!=null&&(!before.rootId().equals(next.rootId())||!before.createdAt().equals(next.createdAt())||!next.readAt().isAfter(before.readAt())))throw invalid();String raw=encode(next);if(raw.getBytes(StandardCharsets.UTF_8).length>CAP)throw invalid();String key=key(next.rootId());int changed=expected==0?sql.update(c->{var s=c.prepareStatement("INSERT INTO runtime_settings(setting_key,value_json,revision,updated_at) VALUES(?,?,1,?)");s.setString(1,key);s.setString(2,raw);s.setTimestamp(3,java.sql.Timestamp.from(next.readAt()),utc());return s;}):sql.update(c->{var s=c.prepareStatement("UPDATE runtime_settings SET value_json=?,revision=revision+1,updated_at=? WHERE setting_key=? AND revision=?");s.setString(1,raw);s.setTimestamp(2,java.sql.Timestamp.from(next.readAt()),utc());s.setString(3,key);s.setLong(4,expected);return s;});if(changed!=1)throw invalid();}
 public static String key(String root){WireValues.id(root,false);return "ops_bh:"+sha(root).substring(0,48);}
 public static int bytes(History value){return encode(value).getBytes(StandardCharsets.UTF_8).length;}
 private static String encode(History h){var mapper=tools.jackson.databind.json.JsonMapper.shared();var v=mapper.createObjectNode();v.put("schema_version","backlog-history-v2");v.put("root_id",h.rootId());v.put("created_at",format(h.createdAt()));v.put("read_at",format(h.readAt()));v.put("stamp",h.stamp());v.put("verified_after",format(h.verifiedAfter()));var m=v.putObject("mutation");m.put("epoch",h.mutation().epoch());m.put("started_at",format(h.mutation().startedAt()));m.put("changed_at",format(h.mutation().changedAt()));m.put("sequence",h.mutation().sequence());nullable(v,"ready",h.ready());nullable(v,"paused",h.paused());var spans=v.putArray("spans");for(var span:h.spans()){var row=spans.addObject();row.put("start",format(span.start()));row.put("end",format(span.end()));nullable(row,"ready",span.ready());nullable(row,"paused",span.globallyPaused());}return JdbcFrozenInputs.canonical(v);}
 private static History decode(String raw,long revision){var v=CanonicalJson.parse(raw);var fields=Set.of("schema_version","root_id","created_at","read_at","stamp","mutation","ready","paused","spans","verified_after");WireValues.object(v,fields,fields);if(!"backlog-history-v2".equals(WireValues.text(v.get("schema_version"))))throw invalid();var m=v.get("mutation");var mf=Set.of("epoch","started_at","changed_at","sequence");WireValues.object(m,mf,mf);var mutation=new Mutation(WireValues.text(m.get("epoch")),WireValues.utcMicroseconds(m.get("started_at")),WireValues.utcMicroseconds(m.get("changed_at")),WireValues.nonnegativeInteger(m.get("sequence")));var array=v.get("spans");if(!array.isArray()||array.isEmpty()||array.size()>10000)throw invalid();var spans=new ArrayList<Span>();for(var row:array){var sf=Set.of("start","end","ready","paused");WireValues.object(row,sf,sf);spans.add(new Span(WireValues.utcMicroseconds(row.get("start")),WireValues.utcMicroseconds(row.get("end")),flag(row.get("ready")),flag(row.get("paused"))));}return new History(WireValues.id(v.get("root_id"),false),WireValues.utcMicroseconds(v.get("created_at")),WireValues.utcMicroseconds(v.get("read_at")),WireValues.sha256(v.get("stamp")),mutation,flag(v.get("ready")),flag(v.get("paused")),spans,WireValues.utcMicroseconds(v.get("verified_after")),revision);}
 private static void nullable(tools.jackson.databind.node.ObjectNode row,String name,Boolean value){if(value==null)row.putNull(name);else row.put(name,value);}
 private static Boolean flag(tools.jackson.databind.JsonNode value){if(value==null)throw invalid();if(value.isNull())return null;if(!value.isBoolean())throw invalid();return value.booleanValue();}
 private static String format(Instant at){return new java.time.format.DateTimeFormatterBuilder().appendInstant(6).toFormatter(Locale.ROOT).format(at);}
 private static long number(Object value){if(value==null||!(value instanceof Number n))throw invalid();long number=n.longValue();if(number<0||number>MAX||new java.math.BigDecimal(value.toString()).compareTo(java.math.BigDecimal.valueOf(number))!=0)throw invalid();return number;}
 private static int integer(Object value){long n=number(value);if(n>Integer.MAX_VALUE)throw invalid();return (int)n;}
 private static Calendar utc(){return Calendar.getInstance(TimeZone.getTimeZone("UTC"));}
 private static Instant time(java.sql.Timestamp value){if(value==null||value.toInstant().getEpochSecond()<0||value.getNanos()%1000!=0)throw invalid();return value.toInstant();}
 private static String sha(String text){try{return HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(text.getBytes(StandardCharsets.UTF_8)));}catch(java.security.NoSuchAlgorithmException e){throw invalid();}}
 private static void readonly(){if(!TransactionSynchronizationManager.isActualTransactionActive()||!TransactionSynchronizationManager.isCurrentTransactionReadOnly()||!Integer.valueOf(TransactionDefinition.ISOLATION_REPEATABLE_READ).equals(TransactionSynchronizationManager.getCurrentTransactionIsolationLevel()))throw invalid();}
 private static void writer(){if(!TransactionSynchronizationManager.isActualTransactionActive()||TransactionSynchronizationManager.isCurrentTransactionReadOnly()||!Integer.valueOf(TransactionDefinition.ISOLATION_READ_COMMITTED).equals(TransactionSynchronizationManager.getCurrentTransactionIsolationLevel()))throw invalid();}
 private static IllegalStateException invalid(){return new IllegalStateException("native backlog history storage unavailable");}
}
